import{a as e,i as t,s as n,t as r}from"./app-CchzzT6L.js";var i=JSON.parse(`{"path":"/docker/did-you-know.html","title":"Did You Know","lang":"en-US","frontmatter":{},"git":{"updatedTime":1750669290000,"contributors":[{"name":"hifat","username":"hifat","email":"logmanxsa@gmail.com","commits":1,"url":"https://github.com/hifat"}],"changelog":[{"hash":"f4f988864af1acf232240d928dcd37f79af2c4ff","time":1750669290000,"email":"logmanxsa@gmail.com","author":"hifat","message":"add docker did you know content"}]},"filePathRelative":"docker/did-you-know.md"}`),a={name:`did-you-know.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="did-you-know" tabindex="-1"><a class="header-anchor" href="#did-you-know"><span>Did You Know</span></a></h1><h2 id="x509-certificate-signed-by-unknown-authority" tabindex="-1"><a class="header-anchor" href="#x509-certificate-signed-by-unknown-authority"><span>x509: certificate signed by unknown authority</span></a></h2><p>คำสั่ง <code>RUN apk add --no-cache ca-certificates</code> มีความสำคัญมากเมื่อคุณทำ image แบบ multi-stage โดยเฉพาะถ้า final stage เป็น <code>distroless</code> image ครับ มาดูความหมายและความจำเป็นกัน:</p><hr><h2 id="🔍-คําอธิบาย" tabindex="-1"><a class="header-anchor" href="#🔍-คําอธิบาย"><span>🔍 คำอธิบาย</span></a></h2><div class="language-docker line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="docker"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#F97583;">RUN</span><span style="color:#E1E4E8;"> apk add --no-cache ca-certificates</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li><code>apk</code> คือ package manager ของ Alpine Linux (เหมือน <code>apt</code> บน Ubuntu)</li><li><code>add</code> คือคำสั่งติดตั้งแพ็กเกจ</li><li><code>--no-cache</code> บอกให้ไม่เก็บ cache ของ index ระหว่างติดตั้ง → ลดขนาด image</li><li><code>ca-certificates</code> คือชุดของ <strong>Certificate Authority (CA)</strong> ที่ระบบใช้ในการตรวจสอบ SSL/TLS certificates</li></ul><hr><h2 id="❓-จําเป็นไหม" tabindex="-1"><a class="header-anchor" href="#❓-จําเป็นไหม"><span>❓ จำเป็นไหม?</span></a></h2><h3 id="✔️-จําเป็นถ้า" tabindex="-1"><a class="header-anchor" href="#✔️-จําเป็นถ้า"><span>✔️ จำเป็นถ้า...</span></a></h3><ul><li><p>แอปของคุณมีการ <strong>เรียก HTTPs ไปยัง external services</strong> เช่น:</p><ul><li>เรียก API ของ Google, AWS, GitHub ฯลฯ</li><li>เชื่อมฐานข้อมูลผ่าน TLS</li><li>ใช้ library อย่าง <code>http.Get(...)</code> ไปยัง <code>https://...</code></li></ul></li></ul><blockquote><p>ถ้าไม่มี <code>ca-certificates</code> เวลา Go app ไปเรียก HTTPS URL จะได้ error เช่น:</p><div class="language-text line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span>x509: certificate signed by unknown authority</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div></blockquote><h3 id="❌-ไม่จําเป็นถ้า" tabindex="-1"><a class="header-anchor" href="#❌-ไม่จําเป็นถ้า"><span>❌ ไม่จำเป็นถ้า...</span></a></h3><ul><li>แอปคุณรันในระบบปิด ไม่มีการเรียก HTTPS ไปข้างนอกเลย (ซึ่งหายาก)</li><li>ใช้ HTTP ล้วน ๆ (ไม่นิยมเพราะไม่ปลอดภัย)</li></ul><hr><h2 id="💡-ทําไมต้อง-copy-ไปยัง-distroless-stage" tabindex="-1"><a class="header-anchor" href="#💡-ทําไมต้อง-copy-ไปยัง-distroless-stage"><span>💡 ทำไมต้อง <code>COPY</code> ไปยัง <code>distroless</code> stage?</span></a></h2><div class="language-docker line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="docker"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#F97583;">COPY</span><span style="color:#E1E4E8;"> --from=builder /etc/ssl/certs/ca-certificates.crt /etc/ssl/certs/</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>เพราะ <code>distroless</code> ไม่มี package manager และไม่มี cert ติดมาให้เลย ถ้าไม่ copy ไปเอง แอปจะหา CA cert ไม่เจอแล้วพังทันที</p><hr><h2 id="✅-สรุป" tabindex="-1"><a class="header-anchor" href="#✅-สรุป"><span>✅ สรุป</span></a></h2><table><thead><tr><th>สิ่งที่ทำ</th><th>ความหมาย / เหตุผล</th></tr></thead><tbody><tr><td><code>apk add --no-cache ca-certificates</code></td><td>ติดตั้ง CA certificates ใน Alpine stage</td></tr><tr><td><code>COPY ... /etc/ssl/certs/</code></td><td>เอา CA cert ไปใส่ใน distroless ที่ไม่มีของพวกนี้</td></tr><tr><td>จำเป็นไหม?</td><td>จำเป็นถ้าแอปของคุณใช้ HTTPS ไปภายนอก</td></tr></tbody></table><hr><p>ถ้าคุณใช้ GRPC/TLS หรือ REST API ผ่าน HTTPS → ต้องใช้แน่นอนครับ ✅ ถ้าอยากลดขนาด image เพิ่มเติม ผมมีเทคนิคอื่นแนะนำได้นะ บอกได้เลย!</p>`,23)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};